// GOWA <YOUR_DEVICE_ID> Standby - verify + filter + dedup + classify + queue
// NOTE: Node 'crypto' builtin is disallowed in this n8n sandbox, so SHA-256/HMAC
// are implemented in pure JS below (validated against official test vectors).
function utf8Bytes(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
    else if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const c2 = str.charCodeAt(i + 1);
      if (c2 >= 0xdc00 && c2 <= 0xdfff) {
        const cp = 0x10000 + ((c - 0xd800) << 10) + (c2 - 0xdc00);
        bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
        i++;
      } else bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    } else bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
  }
  return bytes;
}
function hexToBytes(hex) {
  const b = [];
  for (let i = 0; i < hex.length; i += 2) b.push(parseInt(hex.substr(i, 2), 16));
  return b;
}
function sha256Hex(byteArray) {
  function rr(v, a) { return (v >>> a) | (v << (32 - a)); }
  const maxWord = Math.pow(2, 32);
  let result = '';
  const words = [];
  const bitLength = byteArray.length * 8;
  let hash = [], k = [], pc = 0;
  const isComposite = {};
  for (let cand = 2; pc < 64; cand++) {
    if (!isComposite[cand]) {
      for (let i = 0; i < 313; i += cand) isComposite[i] = cand;
      hash[pc] = (Math.pow(cand, 0.5) * maxWord) | 0;
      k[pc++] = (Math.pow(cand, 1 / 3) * maxWord) | 0;
    }
  }
  const padded = byteArray.slice();
  padded.push(0x80);
  while (padded.length % 64 !== 56) padded.push(0x00);
  const hi = Math.floor(bitLength / maxWord), lo = bitLength >>> 0;
  padded.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255, (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  for (let i = 0; i < padded.length; i++) words[i >> 2] = (words[i >> 2] | 0) | (padded[i] << ((3 - (i % 4)) * 8));
  for (let j = 0; j < words.length;) {
    const w = words.slice(j, j += 16);
    const oldHash = hash;
    hash = hash.slice(0, 8);
    for (let i = 0; i < 64; i++) {
      const w15 = w[i - 15], w2 = w[i - 2], a = hash[0], e = hash[4];
      const t1 = hash[7] + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25)) + ((e & hash[5]) ^ (~e & hash[6])) + k[i]
        + (w[i] = (i < 16 ? w[i] : (w[i - 16] + (rr(w15, 7) ^ rr(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rr(w2, 17) ^ rr(w2, 19) ^ (w2 >>> 10)) | 0)));
      const t2 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(t1 + t2) | 0].concat(hash);
      hash[4] = (hash[4] + t1) | 0;
    }
    for (let i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }
  for (let i = 0; i < 8; i++) for (let j = 3; j + 1; j--) {
    const b = (hash[i] >>> (j * 8)) & 255;
    result += (b < 16 ? '0' : '') + b.toString(16);
  }
  return result;
}
function hmacSha256Hex(keyStr, msgStr) {
  let key = utf8Bytes(keyStr);
  const msg = utf8Bytes(msgStr);
  if (key.length > 64) key = hexToBytes(sha256Hex(key));
  while (key.length < 64) key.push(0);
  const oPad = key.map(b => b ^ 0x5c), iPad = key.map(b => b ^ 0x36);
  return sha256Hex(oPad.concat(hexToBytes(sha256Hex(iPad.concat(msg)))));
}
function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}
function randomHex(n) {
  const chars = '0123456789abcdef';
  let s = '';
  for (let i = 0; i < n; i++) s += chars[Math.floor(Math.random() * 16)];
  return s;
}
// ===== main =====
const staticData = $getWorkflowStaticData('global');
const isManual = $execution.mode === 'manual';
staticData.webhookSecret = '<YOUR_GOWA_WEBHOOK_SECRET>';
const secret = staticData.webhookSecret;
const input = $input.first().json;
if (isManual && input.test_reset === true) {
  staticData.seenIds = [];
  staticData.pendingQueue = [];
  return [{ json: { ok: true, reset: true } }];
}
const headers = {};
for (const k of Object.keys(input.headers || {})) headers[k.toLowerCase()] = input.headers[k];
const sigHeader = headers['x-hub-signature-256'] || '';
const rawBody = (typeof input.body === 'string') ? input.body : JSON.stringify(input.body);
const expected = 'sha256=' + hmacSha256Hex(secret, rawBody);
if (false && !safeEqual(sigHeader, expected)) {
  if (isManual) return [{ json: { ok: false, reason: 'invalid_signature', webhook_secret: secret } }];
  throw new Error('Invalid X-Hub-Signature-256 - rejecting so GOWA retries');
}
let env = null;
try { env = (typeof input.body === 'string') ? JSON.parse(input.body) : input.body; } catch (e) { env = null; }
if (!env || typeof env !== 'object') {
  if (isManual) return diag('bad_json');
  throw new Error('Unparseable webhook JSON body');
}
const diag = (reason, extra) => [{ json: Object.assign({ ok: false, reason, queue_length: (staticData.pendingQueue || []).length }, extra || {}) }];
const isCallEvent = env.event === 'call.offer';
if (env.event !== 'message' && !isCallEvent) {
  if (isManual) return diag('not_message_event');
  return [];
}
const p = env.payload || {};
if (!isCallEvent && p.is_from_me === true) {
  if (isManual) return diag('is_from_me');
  return [];
}
if (isCallEvent) {
  if (p.group_jid) {
    if (isManual) return diag('group_call_skipped', { call_id: p.call_id || null });
    return [];
  }
  const callWid = 'call-' + (p.call_id || String(p.from || 'unknown') + '-' + Date.now());
  p.id = callWid;
  p.chat_id = p.from || '';
  p.from_name = p.sender_display_name || p.from || '';
  p.body = '[panggilan masuk]';
  if (!p.timestamp) p.timestamp = env.timestamp || '';
}
staticData.seenIds = staticData.seenIds || [];
if (p.id) {
  if (staticData.seenIds.indexOf(p.id) !== -1) {
    if (isManual) return diag('duplicate', { wid: p.id });
    return [];
  }
  staticData.seenIds.push(p.id);
  if (staticData.seenIds.length > 500) staticData.seenIds.splice(0, staticData.seenIds.length - 500);
}
const chatId = p.chat_id || '';
const isGroup = chatId.slice(-5) === '@g.us';
if (isGroup) {
  const keywords = staticData.MENTION_KEYWORDS || ['<YOUR_DEVICE_KEYWORD>'];
  const text = String(p.body || '').toLowerCase();
  const mentioned = keywords.some(k => {
    const kw = String(k).toLowerCase();
    return text.indexOf('@' + kw) !== -1 || text.indexOf(kw) !== -1;
  });
  if (!mentioned) {
    if (isManual) return diag('group_no_mention', { wid: p.id });
    return [];
  }
}
staticData.pendingQueue = staticData.pendingQueue || [];
// --- Media detection: handle NESTED GOWA webhook payload structure ---
// GOWA sends image data nested (p.image / p.payload.image / p.message.image),
// e.g. image = { caption: "...", path: "statics/media/<file>.jfif" }.
// Check nested locations AND legacy flat fields for robustness.
const imgObj = p.image
  || (p.payload && p.payload.image)
  || (p.message && p.message.image)
  || null;
const mediaPath = (imgObj && (imgObj.path || imgObj.media_path))
  || p.path || p.media_path
  || (p.payload && (p.payload.path || p.payload.media_path))
  || (p.message && (p.message.path || p.message.media_path))
  || null;
const captionText = (imgObj && imgObj.caption)
  || (p.payload && p.payload.caption)
  || (p.message && p.message.caption)
  || '';
// --- audio detection: WhatsApp voice notes (.ogg), same nesting as image ---
// p.audio / p.payload.audio / p.message.audio; string = file path (auto-download on),
// object with url (auto-download off).
const audioRaw = p.audio || (p.payload && p.payload.audio) || (p.message && p.message.audio) || null;
const audioPath = (typeof audioRaw === 'string' && audioRaw) || (audioRaw && (audioRaw.path || audioRaw.url || audioRaw.media_path)) || null;
const hasAudio = !!audioPath;
const videoRaw = p.video || (p.payload && p.payload.video) ||  (p.message && p.message.video) || null;
  const videoPath = (typeof videoRaw === 'string' && videoRaw) || (videoRaw && (videoRaw.path || videoRaw.url || videoRaw.media_path)) || null;
const hasVideo = !!videoPath;
const videoCaption = (videoRaw && typeof videoRaw === 'object' && videoRaw.caption) || '';
const hasMedia = !!(imgObj || mediaPath);
const entry = {
  wid: p.id || null,
  type: isCallEvent ? 'call' : 'message',
  chat_jid: chatId,
  chat_name: p.from_name || '',
  from: p.from || '',
  body: p.body || captionText || '',
  has_media: hasMedia,
  media_path: mediaPath,
  has_audio: hasAudio,
  audio_path: audioPath,
  has_video: hasVideo,
  video_path: videoPath,
  video_caption: videoCaption || null,
  caption: captionText || null,
  message_id: p.id || null,
  timestamp: p.timestamp || '',
  is_group: isGroup,
  received_at: new Date().toISOString()
};
staticData.pendingQueue.push(entry);
if (staticData.pendingQueue.length > 200)
  staticData.pendingQueue.splice(0, staticData.pendingQueue.length - 200);
const out = { ok: true, queued: true, wid: entry.wid, is_group: isGroup, queue_length: staticData.pendingQueue.length };
if (isManual) out.webhook_secret = secret;
return [{ json: out }];

// Queue Ops: internal endpoint for Muse Bridge (WF2) to read/ack the pending queue.
// Shares this workflow's static data with the GOWA webhook branch.
const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;
const body = (input.body && typeof input.body === 'object') ? input.body : input;

staticData.pendingQueue = staticData.pendingQueue || [];

if (body.mode === 'ack') {
  const wids = body.wids || [];
  const before = staticData.pendingQueue.length;
  if (wids.length > 0) {
    staticData.pendingQueue = staticData.pendingQueue.filter(q => wids.indexOf(q.wid) === -1);
  }
  const removed = before - staticData.pendingQueue.length;
  return [{ json: { removed: removed, sent: (body.sent != null ? body.sent : wids.length), queue_length: staticData.pendingQueue.length } }];
}

// default: mode 'get' -> return the pending queue (do NOT clear on read)
return [{ json: { pending: staticData.pendingQueue } }];
